function evidence = f90_xtherm08_extract_reference_evidence(modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XTHERM08_EXTRACT_REFERENCE_EVIDENCE One-session six-scenario replay.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end
modelFile = modelPath;
outDir = outputDir;
assert(isfile(officialScenarios), "SimuVerity:F90:XTHERM08:OfficialScenarios", ...
    "Official scenarios are missing.");
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XTHERM08:ReferenceAssetRoot", ...
    "Evaluator asset root is missing.");
official = jsondecode(fileread(officialScenarios));
referenceRoot = evaluatorAssetRoot;
expectedPresence = lower(strtrim(string("present")));
assert(strcmpi(localFilePresence(modelFile), expectedPresence), ...
    "SimuVerity:F90:XTHERM08:ReferenceIdentity", ...
    "Reference file presence differs from the task binding.");
supportNames = ["DataCenterCoolingEnviornment.mat"; ...
    "DataCenterCoolingHeatLoad.mat"];
supportBindings = [ ...
    "present"; ...
    "present"];
for supportIndex = 1:numel(supportNames)
    supportPath = fullfile(referenceRoot, supportNames(supportIndex));
    assert(isfile(supportPath) && ...
        strcmpi(localFilePresence(supportPath), supportBindings(supportIndex)), ...
        "SimuVerity:F90:XTHERM08:SupportIdentity", ...
        "Reference support-file file presence differs.");
end

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XTHERM08:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(~isfolder(outDir), "SimuVerity:F90:XTHERM08:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.", generationRunId);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XTHERM08:Isolation", ...
    "Isolated Simulink cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");

evidence = struct( ...
    "schema", "simuverity.f90-xtherm08-evidence.v1", ...
    "task_id", "F90-XTHERM-08", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "";
oldFolder = pwd;
folderCleanup = onCleanup(@() cd(oldFolder)); %#ok<NASGU>
try
    cd(referenceRoot);
    modelHandle = load_system(modelFile);
    model = string(get_param(modelHandle, "Name"));
    modelCleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;
    localForceCanonicalVariants(model);
    paths = localModelPaths(model);
    localInstallMeasurementTaps(model, paths);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "StopTime", "604800", ...
        "SignalLogging", "on", ...
        "SignalLoggingName", "logsout", ...
        "SimscapeLogType", "all", ...
        "SimscapeLogLimitData", "off");

    baseProfiles = struct( ...
        "heat_load", evalin("base", "heat_load"), ...
        "environment", evalin("base", "environment"));
    baseParameters = struct( ...
        "chilled_gain", string(get_param(paths.chilled_gain, "Gain")), ...
        "chiller_power", string(get_param(paths.chiller_power, "gain")));

    localApplyScenario(paths, official.scenarios(1), ...
        baseProfiles, baseParameters);
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model, paths);

    previousStop = string(get_param(model, "StopTime"));
    set_param(model, "StopTime", "3600");
    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke
    set_param(model, "StopTime", previousStop);

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            localApplyScenario(paths, scenario, ...
                baseProfiles, baseParameters);
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut);
            rows(k) = localFinalizeScenario(rows(k), outputs);
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModel(model);
evidence.model_closed_without_save = strlength(model) == 0 || ~bdIsLoaded(model);
evidence.finished_at = localNow;
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
validScenarioCount = 0;
if ~isempty(evidence.scenarios) && isfield(evidence.scenarios, "valid")
    validScenarioCount = sum([evidence.scenarios.valid]);
end
fprintf("F90_XTHERM08_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validScenarioCount, ...
    numel(evidence.scenarios), evidencePath);
end

function localEnsureReference(referenceRoot, reference)
if ~isfolder(referenceRoot), mkdir(referenceRoot); end
modelFile = fullfile(referenceRoot, "DataCenterCooling.slx");
supportNames = ["DataCenterCoolingEnviornment.mat", ...
    "DataCenterCoolingHeatLoad.mat"];
allPresent = isfile(modelFile);
for name = supportNames
    allPresent = allPresent && isfile(fullfile(referenceRoot, name));
end
if ~allPresent
    openExample("simscapefluids/DataCenterCoolingExample", ...
        supportingFile="DataCenterCooling.slx");
    model = "DataCenterCooling";
    assert(bdIsLoaded(model), "SimuVerity:F90:XTHERM08:Acquire", ...
        "The installed R2025a example did not open.");
    sourceModel = string(get_param(model, "FileName"));
    sourceDir = fileparts(sourceModel);
    if ~isfile(modelFile)
        [pass, message] = copyfile(sourceModel, modelFile);
        assert(pass, "SimuVerity:F90:XTHERM08:Acquire", "%s", message);
    end
    for name = supportNames
        target = fullfile(referenceRoot, name);
        if isfile(target), continue; end
        candidate = fullfile(sourceDir, name);
        if ~isfile(candidate)
            candidate = which(name);
        end
        if isempty(candidate) || ~isfile(candidate)
            openExample("simscapefluids/DataCenterCoolingExample", ...
                supportingFile=name);
            candidate = which(name);
        end
        assert(~isempty(candidate) && isfile(candidate), ...
            "SimuVerity:F90:XTHERM08:AcquireSupport", ...
            "Could not acquire official support file %s.", name);
        [pass, message] = copyfile(candidate, target);
        assert(pass, "SimuVerity:F90:XTHERM08:AcquireSupport", "%s", message);
    end
    close_system(model, 0);
end
assert(strcmpi(localFilePresence(modelFile), reference.file_presence), ...
    "SimuVerity:F90:XTHERM08:ReferenceBinding", ...
    "Pinned official model binding mismatch.");
expectedBindings = [ ...
    "present", ...
    "present"];
for k = 1:numel(supportNames)
    name = supportNames(k);
    expected = expectedBindings(k);
    assert(strcmpi(localFilePresence(fullfile(referenceRoot, name)), expected), ...
        "SimuVerity:F90:XTHERM08:SupportBinding", ...
        "Pinned official support-file binding mismatch: %s", name);
end
end

function localForceCanonicalVariants(model)
set_param(model + "/Chiller", ...
    "OverrideUsingVariant", "abstract model");
set_param(localFindChild(model + "/Server Farm", "Variant Source"), ...
    "OverrideUsingVariant", "variable load");
set_param(localFindChild(model + "/Cooling Tower", "Variant Source"), ...
    "OverrideUsingVariant", "variable environment");
end

function paths = localModelPaths(model)
paths = struct;
paths.measurements = localFindRoot(model, "Measurements");
paths.chilled_pump = localFindRoot(model, "Chilled Water Pump");
paths.condenser_pump = localFindRoot(model, "Condenser Water Pump");
paths.chilled_drive = localFindRoot(model, "Chilled Water Pump Drive");
paths.condenser_drive = localFindRoot(model, "Condenser Water Pump Drive");
paths.chiller = localFindRoot(model, "Chiller");
paths.cooling_tower = localFindRoot(model, "Cooling Tower");
paths.heat_exchanger = localFindRoot(model, "Heat Exchanger");
paths.server_farm = localFindRoot(model, "Server Farm");
paths.chilled_controller = localFindChild(paths.chilled_drive, "Controller");
paths.condenser_controller = localFindChild(paths.condenser_drive, "Controller");
paths.chilled_gain = localFindChild(paths.chilled_controller, "Gain");
paths.abstract_chiller = localFindChild(paths.chiller, "Abstract Model");
paths.chiller_controller = localFindChild(paths.abstract_chiller, "Controller");
paths.chiller_power = localFindChild(paths.abstract_chiller, "Nominal Power");
paths.ambient_temperature = ...
    localFindChild(paths.cooling_tower, "Temperature");
paths.relative_humidity = ...
    localFindChild(paths.cooling_tower, "Relative Humidity");
end

function localInstallMeasurementTaps(model, paths)
localTap(model, paths.measurements, 1, "f90_heat_W");
localTap(model, paths.measurements, 2, "f90_temperature_C");
localTap(model, paths.measurements, 3, "f90_power_W");
localTap(paths.chilled_drive, paths.chilled_controller, ...
    1, "f90_chilled_command");
localTap(paths.condenser_drive, paths.condenser_controller, ...
    1, "f90_condenser_command");
localTap(paths.abstract_chiller, paths.chiller_controller, ...
    1, "f90_chiller_command");
localTap(paths.cooling_tower, paths.ambient_temperature, ...
    1, "f90_ambient_temperature_C");
localTap(paths.cooling_tower, paths.relative_humidity, ...
    1, "f90_relative_humidity");
end

function localTap(parent, source, port, variable)
tap = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(tap) < 0, ...
    "SimuVerity:F90:XTHERM08:TapCollision", ...
    "Temporary measurement tap already exists.");
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(sourcePorts.Outport(port) > 0 && tapPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XTHERM08:TapPort", "A required real source port is missing.");
add_line(parent, sourcePorts.Outport(port), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(paths, scenario, baseProfiles, baseParameters)
assignin("base", "ServerLoadScale", ...
    double(scenario.ServerLoadScale));
assignin("base", "AmbientTemperatureOffset_C", ...
    double(scenario.AmbientTemperatureOffset_C));
assignin("base", "RelativeHumidityScale", ...
    double(scenario.RelativeHumidityScale));
assignin("base", "ChilledWaterPumpCapacityScale", ...
    double(scenario.ChilledWaterPumpCapacityScale));
assignin("base", "ChillerCapacityScale", ...
    double(scenario.ChillerCapacityScale));
assignin("base", "heat_load", localScaleProfile( ...
    baseProfiles.heat_load, double(scenario.ServerLoadScale)));
assignin("base", "environment", localEnvironmentProfile( ...
    baseProfiles.environment, ...
    double(scenario.AmbientTemperatureOffset_C), ...
    double(scenario.RelativeHumidityScale)));

baseChilledGain = localEvaluateExpression(baseParameters.chilled_gain);
set_param(paths.chilled_gain, "Gain", sprintf("%.17g", ...
    baseChilledGain * double(scenario.ChilledWaterPumpCapacityScale)));
baseChillerPower = localEvaluateExpression(baseParameters.chiller_power);
set_param(paths.chiller_power, "gain", sprintf("%.17g", ...
    baseChillerPower * double(scenario.ChillerCapacityScale)));
end

function result = localScaleProfile(value, scale)
result = value;
if isa(value, "timeseries")
    result.Data = double(value.Data) .* scale;
elseif istimetable(value)
    result.Variables = double(value.Variables) .* scale;
elseif isnumeric(value)
    result = double(value);
    if size(result, 2) >= 2 && localLooksLikeTime(result(:, 1))
        result(:, 2:end) = result(:, 2:end) .* scale;
    else
        result = result .* scale;
    end
elseif isstruct(value) && isfield(value, "signals") ...
        && isfield(value.signals, "values")
    result.signals.values = double(value.signals.values) .* scale;
else
    error("SimuVerity:F90:XTHERM08:HeatProfileType", ...
        "Unsupported heat-load profile type %s.", class(value));
end
end

function result = localEnvironmentProfile(value, offset, humidityScale)
result = value;
if isa(value, "timeseries")
    data = double(value.Data);
    data(:, 1) = data(:, 1) + offset;
    data(:, 2) = min(1, max(0, data(:, 2) .* humidityScale));
    result.Data = data;
elseif istimetable(value)
    data = double(value.Variables);
    data(:, 1) = data(:, 1) + offset;
    data(:, 2) = min(1, max(0, data(:, 2) .* humidityScale));
    result.Variables = data;
elseif isnumeric(value)
    result = double(value);
    firstData = 1;
    if size(result, 2) >= 3 && localLooksLikeTime(result(:, 1))
        firstData = 2;
    end
    assert(size(result, 2) >= firstData + 1, ...
        "SimuVerity:F90:XTHERM08:EnvironmentColumns", ...
        "Environment profile must contain temperature and humidity.");
    result(:, firstData) = result(:, firstData) + offset;
    result(:, firstData + 1) = min(1, max(0, ...
        result(:, firstData + 1) .* humidityScale));
elseif isstruct(value) && isfield(value, "signals") ...
        && isfield(value.signals, "values")
    data = double(value.signals.values);
    data(:, 1) = data(:, 1) + offset;
    data(:, 2) = min(1, max(0, data(:, 2) .* humidityScale));
    result.signals.values = data;
else
    error("SimuVerity:F90:XTHERM08:EnvironmentProfileType", ...
        "Unsupported environment profile type %s.", class(value));
end
end

function pass = localLooksLikeTime(values)
values = double(values(:));
pass = numel(values) >= 2 && all(isfinite(values)) && ...
    all(diff(values) >= 0) && max(values) > min(values);
end

function value = localEvaluateExpression(expression)
try
    value = evalin("base", char(expression));
catch
    value = str2double(expression);
end
assert(isscalar(value) && isfinite(value), ...
    "SimuVerity:F90:XTHERM08:ParameterExpression", ...
    "Could not evaluate a real reference parameter.");
value = double(value);
end

function localValidateSmoke(simOut)
required = ["f90_heat_W", "f90_temperature_C", "f90_power_W", ...
    "f90_chilled_command", "f90_condenser_command", ...
    "f90_chiller_command", "f90_ambient_temperature_C", ...
    "f90_relative_humidity"];
for name = required
    value = localGetOutput(simOut, name);
    assert(isa(value, "timeseries") && numel(value.Time) >= 2, ...
        "SimuVerity:F90:XTHERM08:SmokeTap", ...
        "Smoke run did not produce required Timeseries %s.", name);
end
end

function outputs = localExtractOutputs(simOut)
heat = localWorkspaceTimeseries(simOut, "f90_heat_W", 4);
temperature = localWorkspaceTimeseries(simOut, ...
    "f90_temperature_C", 5);
power = localWorkspaceTimeseries(simOut, "f90_power_W", 5);
chilledCommand = localWorkspaceTimeseries(simOut, ...
    "f90_chilled_command", 1);
condenserCommand = localWorkspaceTimeseries(simOut, ...
    "f90_condenser_command", 1);
chillerCommand = localWorkspaceTimeseries(simOut, ...
    "f90_chiller_command", 1);
ambient = localWorkspaceTimeseries(simOut, ...
    "f90_ambient_temperature_C", 1);
humidity = localWorkspaceTimeseries(simOut, ...
    "f90_relative_humidity", 1);
simlog = localGetOutput(simOut, "simlog_DataCenterCooling");
assert(~isempty(simlog), "SimuVerity:F90:XTHERM08:SimscapeLog", ...
    "The native Simscape log is missing.");
chilledFlow = localNativeSeries(simlog, ...
    ["Chilled_Water_Pump", "mdot_A"], "kg/s");
condenserFlow = localNativeSeries(simlog, ...
    ["Condenser_Water_Pump", "mdot_A"], "kg/s");
evaporation = localNativeSeries(simlog, ...
    ["Cooling_Tower", "Cooling_Tower", "E"], "kg/s");

time = linspace(0, 604800, 4000)';
outputs = struct( ...
    "time_s", time, ...
    "thermal_state", localInterpMatrix(temperature, time), ...
    "flow_control_state", [ ...
        localInterpMatrix(chilledFlow, time), ...
        localInterpMatrix(condenserFlow, time), ...
        localInterpMatrix(chilledCommand, time), ...
        localInterpMatrix(condenserCommand, time), ...
        localInterpMatrix(chillerCommand, time)], ...
    "heat_power_state", [ ...
        localInterpMatrix(heat, time), ...
        localInterpMatrix(power, time)], ...
    "environment_state", [ ...
        localInterpMatrix(ambient, time), ...
        localInterpMatrix(humidity, time), ...
        localInterpMatrix(evaporation, time)]);
end

function row = localFinalizeScenario(row, outputs)
allValues = [outputs.time_s; outputs.thermal_state(:); ...
    outputs.flow_control_state(:); outputs.heat_power_state(:); ...
    outputs.environment_state(:)];
row.simulation_pass = true;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    numel(outputs.time_s) >= 1000 && ...
    outputs.time_s(1) == 0 && outputs.time_s(end) >= 604800;
row.valid = row.required_evidence_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(model, paths)
fromBlocks = find_system(model, "LookUnderMasks", "all", ...
    "FollowLinks", "on", "BlockType", "From");
tags = strings(size(fromBlocks));
for k = 1:numel(fromBlocks)
    tags(k) = string(get_param(fromBlocks{k}, "GotoTag"));
end
requiredTags = ["T_evap_outlet", "T_server_outlet", ...
    "T_cond_outlet", "T_tower_outlet"];
tagPass = all(arrayfun(@(tag) any(tags == tag), requiredTags));
rootPaths = [paths.chilled_pump, paths.condenser_pump, ...
    paths.heat_exchanger, paths.server_farm, ...
    paths.chiller, paths.cooling_tower];
audit = struct( ...
    "physical_core_block_count", sum(arrayfun( ...
        @(path) getSimulinkBlockHandle(path) > 0, rootPaths)), ...
    "two_distinct_physical_pumps", ...
        paths.chilled_pump ~= paths.condenser_pump, ...
    "three_controller_outputs_present", ...
        getSimulinkBlockHandle(paths.chilled_controller) > 0 && ...
        getSimulinkBlockHandle(paths.condenser_controller) > 0 && ...
        getSimulinkBlockHandle(paths.chiller_controller) > 0, ...
    "required_feedback_tags_present", tagPass, ...
    "abstract_chiller_active", ...
        string(get_param(paths.chiller, "LabelModeActiveChoice")) == ...
        "abstract model", ...
    "variable_load_active", ...
        string(get_param(localFindChild(paths.server_farm, ...
        "Variant Source"), "LabelModeActiveChoice")) == "variable load", ...
    "variable_environment_active", ...
        string(get_param(localFindChild(paths.cooling_tower, ...
        "Variant Source"), "LabelModeActiveChoice")) == ...
        "variable environment");
audit.core_path_qualified = ...
    audit.physical_core_block_count == 6 && ...
    audit.two_distinct_physical_pumps && ...
    audit.three_controller_outputs_present && ...
    audit.required_feedback_tags_present && ...
    audit.abstract_chiller_active && ...
    audit.variable_load_active && ...
    audit.variable_environment_active;
end

function path = localFindRoot(model, normalizedName)
blocks = find_system(model, "SearchDepth", 1, "Type", "Block");
path = localSelectNormalized(blocks, normalizedName);
end

function path = localFindChild(parent, normalizedName)
blocks = find_system(parent, "SearchDepth", 1, "Type", "Block");
blocks = blocks(~strcmp(blocks, parent));
path = localSelectNormalized(blocks, normalizedName);
end

function path = localSelectNormalized(blocks, expected)
matches = strings(0, 1);
for k = 1:numel(blocks)
    name = string(get_param(blocks{k}, "Name"));
    normalized = regexprep(name, "\s+", " ");
    if strcmpi(strtrim(normalized), expected)
        matches(end + 1, 1) = string(blocks{k}); %#ok<AGROW>
    end
end
assert(numel(matches) == 1, "SimuVerity:F90:XTHERM08:BlockLookup", ...
    "Expected one block named %s, found %d.", expected, numel(matches));
path = matches(1);
end

function series = localWorkspaceTimeseries(simOut, name, columns)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XTHERM08:WorkspaceTap", ...
    "Required measurement tap %s is missing.", name);
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data, 1) ~= numel(value.Time) && ...
        size(data, 2) == numel(value.Time)
    data = data.';
end
assert(size(data, 1) == numel(value.Time) && ...
    size(data, 2) == columns, "SimuVerity:F90:XTHERM08:WorkspaceShape", ...
    "Tap %s has unexpected dimensions.", name);
series = struct( ...
    "time", double(value.Time(:)), ...
    "values", data);
end

function series = localNativeSeries(node, ids, unit)
for k = 1:numel(ids)
    node = node.(char(ids(k)));
end
native = node.series;
nativeTime = native.time;
nativeValues = native.values(char(unit));
series = struct( ...
    "time", double(nativeTime(:)), ...
    "values", squeeze(double(nativeValues)));
end

function values = localInterpMatrix(series, time)
assert(~isempty(series.time) && ~isempty(series.values), ...
    "SimuVerity:F90:XTHERM08:EmptySeries", ...
    "Required physical series is empty.");
data = double(series.values);
if isvector(data), data = data(:); end
if size(data, 1) ~= numel(series.time) && ...
        size(data, 2) == numel(series.time)
    data = data.';
end
assert(size(data, 1) == numel(series.time), ...
    "SimuVerity:F90:XTHERM08:SeriesShape", ...
    "Required physical series has unexpected dimensions.");
values = interp1(double(series.time(:)), data, ...
    time, "linear", "extrap");
end

function value = localGetOutput(simOut, name)
value = [];
try, value = simOut.get(name); catch, end
if isempty(value)
    try, value = evalin("base", name); catch, end
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message));
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid > 0, "SimuVerity:F90:XTHERM08:JsonWrite", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end

function root = localRepoRoot
root = fileparts(fileparts(fileparts(fileparts( ...
    fileparts(mfilename("fullpath"))))));
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
